// TWO headers, because Vercel does not honour `s-maxage` written into `cache-control` on a
// force-dynamic route handler. `cdn-cache-control` is the one the edge reads, and it is never
// forwarded to a browser.
export const dynamic = 'force-dynamic';
const CACHE = {
  'cache-control': 'public, max-age=0, must-revalidate',
  'cdn-cache-control': 'public, s-maxage=600, stale-while-revalidate=86400',
};

/** GET /api/freshness — when the catalogue was last checked against the vendors' own pages. */
export async function GET() {
  const services = await getCatalogue({ fresh: true });
  const fresh = freshness(services);
  const run = await getLastRefresh({ fresh: true });
  const stale = fresh.oldest ? Date.now() - Date.parse(fresh.oldest) > 3 * 86400_000 : true;
  return NextResponse.json({
    oldest_verified_at: fresh.oldest,
    newest_verified_at: fresh.newest,
    rows_needing_attention: fresh.drifted,
    stale,
    last_run: run,
  }, { headers: CACHE });
}
